import java.util.Objects;
import java.util.concurrent.ConcurrentHashMap;
import java.util.stream.Collectors;
import static software.amazon.event.ruler.SetOperations.intersection;
import org.mockito.*;
import org.junit.jupiter.api.*;
import static org.mockito.Mockito.*;
import static org.junit.jupiter.api.Assertions.*;

class GenericMachine_approximateObjectCount_35_0_Test {

    /**
     * A Test helper that overrides NameState.gatherObjects to controllably add objects.
     *
     * Note: This class relies on the (observed) signature:
     *   public void gatherObjects(Set<Object> objectSet, int maxObjectCount)
     * in the real NameState class.
     */
    static class CountingNameState extends NameState {

        private final int toAdd;

        private final boolean respectMax;

        CountingNameState(int toAdd, boolean respectMax) {
            this.toAdd = toAdd;
            this.respectMax = respectMax;
        }

        @Override
        public void gatherObjects(Set<Object> objectSet, int maxObjectCount) {
            // If respectMax is true, stop at maxObjectCount.
            int limit = respectMax ? Math.min(toAdd, maxObjectCount) : toAdd;
            for (int i = 0; i < limit; i++) {
                // Use distinct objects to ensure set size increments.
                objectSet.add(new StringBuilder("obj-" + i).toString());
            }
        }
    }

    // Helper to replace the private final startState field via reflection
    private static void replaceStartState(GenericMachine machine, NameState replacement) throws Exception {
        Field startField = GenericMachine.class.getDeclaredField("startState");
        startField.setAccessible(true);
        // Remove final modifier if present to allow setting the field value
        try {
            Field modifiersField = Field.class.getDeclaredField("modifiers");
            modifiersField.setAccessible(true);
            modifiersField.setInt(startField, startField.getModifiers() & ~Modifier.FINAL);
        } catch (NoSuchFieldException ignored) {
            // Some JVMs may not have modifiers field; ignore in that case.
        }
        startField.set(machine, replacement);
    }

    @Test
    void approximateObjectCount_respectsMaxAndCountsObjects() throws Exception {
        // arrange
        GenericMachineConfiguration cfg = new GenericMachineConfiguration(false, false);
        GenericMachine machine = new GenericMachine(cfg);
        // replace start state with one that will add 5 objects and respects max
        replaceStartState(machine, new CountingNameState(5, true));
        // act & assert
        int counted = machine.approximateObjectCount(3);
        assertEquals(3, counted, "Should return min(actualObjects, maxObjectCount)");
        // a larger max should return full count (5)
        int fullCount = machine.approximateObjectCount(10);
        assertEquals(5, fullCount, "Should return actual object count when max is large enough");
    }

    @Test
    void deprecatedNoArgApproximateObjectCount_delegatesToMaxInt() throws Exception {
        // arrange
        GenericMachineConfiguration cfg = new GenericMachineConfiguration(false, false);
        GenericMachine machine = new GenericMachine(cfg);
        // replace start state with one that will add 7 objects and respects max
        replaceStartState(machine, new CountingNameState(7, true));
        // act
        // deprecated no-arg delegates to int-max
        int result = machine.approximateObjectCount();
        // assert
        assertEquals(7, result, "No-arg deprecated method should delegate to approximateObjectCount(Integer.MAX_VALUE)");
    }

    @Test
    void approximateObjectCount_withZeroMaxReturnsZero() throws Exception {
        // arrange
        GenericMachineConfiguration cfg = new GenericMachineConfiguration(false, false);
        GenericMachine machine = new GenericMachine(cfg);
        // replace start state with one that would add objects (but should respect max)
        replaceStartState(machine, new CountingNameState(100, true));
        // act
        int result = machine.approximateObjectCount(0);
        // assert
        assertEquals(0, result, "If maxObjectCount is zero, returned count must be zero");
    }

    @Test
    void approximateObjectCount_whenNameStateIgnoresMaxStillHonorsProvidedMax() throws Exception {
        // arrange
        GenericMachineConfiguration cfg = new GenericMachineConfiguration(false, false);
        GenericMachine machine = new GenericMachine(cfg);
        // replace start state with one that does NOT respect max (will attempt to add 10)
        replaceStartState(machine, new CountingNameState(10, false));
        // act: even if NameState ignores max, approximateObjectCount returns min(size, max)
        int result = machine.approximateObjectCount(4);
        // Because our fake NameState will attempt to add 10 distinct objects, objectSet.size() will be 10,
        // so the method should return min(10, 4) = 4.
        assertEquals(4, result, "Result should be min(objectSet.size(), maxObjectCount) even if NameState ignores max argument");
    }

    @Test
    void approximateObjectCount_returnsZeroWhenNameStateAddsNoObjects() throws Exception {
        // arrange
        GenericMachineConfiguration cfg = new GenericMachineConfiguration(false, false);
        GenericMachine machine = new GenericMachine(cfg);
        // replace start state with one that will add 0 objects
        replaceStartState(machine, new CountingNameState(0, true));
        // act
        int result = machine.approximateObjectCount(100);
        // assert
        assertEquals(0, result, "If NameState adds no objects the count should be zero");
    }
}
